 body {
  background-color: #f6f6f6;
}

  /* Styling for the floating WhatsApp button */
  .floating-whatsapp {
      position: fixed;
      bottom: 20px;
      right: 20px;
      z-index: 999;
      padding: 10px;
    }

.search-bar {
      margin-bottom: 20px;
    }

    .search-input {
      width: 300px;
      padding: 6px;
    }

.fa-file {
  display: none;
}

/* Navbar */
.navbar-brand {
  text-decoration: none;
}

    .navbar-brand-content {
      display: flex;
      align-items: center;
    }

    .navbar-brand-text {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      margin-left: 10px;
    }

    .navbar-brand-title {
      font-weight: bold;
      text-decoration: none;
      animation: blink 3s infinite;
    }

    .navbar-brand-motto {
      font-size: 12px;
      color: #888;
      margin-top: 5px;
    }

    .navbar {
      position: sticky;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background-color: #fff;
      padding: 10px 20px;
      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
    }

    /* Adjust the height and padding of the navbar */
    .navbar {
      height: 80px;
      padding: 10px 20px;
    }

.free-price {
      color: red;
      text-decoration: line-through;
    }
    .free-text {
      color: green;
    }
